test('DP Memory Berry provides earlier-stage attacks and remains attached after the turn',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.active.cards=[];dpPut(m,'dp1-76',p.active);const top=new R.PokemonCard();Object.assign(top,{id:-890001,name:'Evolution fixture',fullName:'Evolution fixture',stage:R.Stage.STAGE_1,hp:100,attacks:[{name:'Top hit',cost:[],damage:10,text:''}],powers:[]});p.active.cards.push(top);const berry=dpPut(m,'pl1-110',p.active);p.active.tools.push(berry);assert.ok(M.attacks(m,p).some(a=>a.name==='Scratch'));M.apply(m,{type:'pass',player:p.id});drain(m);assert.ok(p.active.tools.includes(berry));});
test('Energy Link exposes a Tool action and moves an attached Energy without reattaching it',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.active.cards=[];p.bench[0].cards=[];dpPut(m,'dp1-76',p.active);dpPut(m,'dp1-76',p.bench[0]);for(const list of [p.active,p.bench[0]]){const tool=dpPut(m,'dp7-83',list);list.tools.push(tool);}const energy=dpPut(m,'tk-dp-m-12',p.active);assert.ok(M.powers(m,p,p.active).some(power=>power.name==='Energy Link'));M.apply(m,{type:'ability',player:p.id,name:'Energy Link',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}]);drain(m);assert.ok(p.bench[0].cards.includes(energy));assert.ok(!p.active.cards.includes(energy));});

