test('Close Combat increases incoming damage after Weakness rather than before it',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const infernape=dpPut(m,'dp7-3',p.active);infernape.hp=500;infernape.weakness=[{type:R.CardType.FIRE}];dpPut(m,'tk-dp-m-12',p.active);dpPut(m,'tk-dp-m-12',p.active);const chimchar=dpPut(m,'dp1-76',o.active);chimchar.hp=500;dpPut(m,'base1-98',o.active);dpPut(m,'base1-98',o.active);M.apply(m,{type:'attack',player:p.id,name:'Close Combat'});drain(m);M.apply(m,{type:'attack',player:o.id,name:'Ember'});drain(m);assert.equal(p.active.damage,90);});
test('Gravitation affects both players but multiple copies do not stack',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.bench[0].cards=[];p.bench[1].cards=[];dpPut(m,'pl3-7',p.bench[0]);dpPut(m,'pl3-7',p.bench[1]);for(const owner of [p,o]){const hp=new R.CheckHpEffect(owner,owner.active);m.store.reduceEffect(m.store.state,hp);assert.equal(hp.hp,owner.active.getPokemonCard().hp-20);}});
test('Two Poke Healer Plus heal eighty and clear every condition while consuming both cards',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.getPokemonCard().hp=200;p.active.damage=90;p.active.specialConditions=[R.SpecialCondition.POISONED,R.SpecialCondition.BURNED];p.hand.cards=[];const copies=[dpPut(m,'dp7-90',p.hand),dpPut(m,'dp7-90',p.hand)];M.apply(m,{type:'play',player:p.id,index:0,target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);assert.equal(p.active.damage,10);assert.equal(p.active.specialConditions.length,0);assert.ok(copies.every(card=>p.discard.cards.includes(card)));});

test('Jamming waits for Supporter resolution and multiple copies place counters only once',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.supporterTurn=0;for(let i=0;i<2;i++){o.bench[i].cards=[];dpPut(m,'dp3-1',o.bench[i]);}p.hand.cards=[];dpPut(m,'pl4-90',p.hand);M.apply(m,{type:'play',player:p.id,index:0,target});drain(m);assert.equal(p.active.damage,0);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);assert.equal(p.active.damage,10);});

test('Corrected Waterlog accepts non-Water basic Energy and ends the turn even when none attach',()=>{for(const attach of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];dpPut(m,'dp3-2',p.active);p.hand.cards=[];let energy;if(attach)energy=dpPut(m,'base1-98',p.hand);M.apply(m,{type:'ability',player:p.id,name:'Waterlog',target});drain(m);if(attach){let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);assert.ok(p.active.cards.includes(energy));}assert.equal(m.store.state.players[m.store.state.activePlayer].id,o.id);}});
test('Sleep recovery modifiers reset when sleep is removed or reapplied',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0],list=p.active;list.addSpecialCondition(R.SpecialCondition.ASLEEP);list.sleepFlips=2;list.dpSleepKoTails=true;list.removeSpecialCondition(R.SpecialCondition.ASLEEP);assert.equal(list.sleepFlips,1);assert.equal(list.dpSleepKoTails,false);list.addSpecialCondition(R.SpecialCondition.ASLEEP);list.sleepFlips=2;list.dpSleepKoTails=true;list.addSpecialCondition(R.SpecialCondition.ASLEEP);assert.equal(list.sleepFlips,1);assert.equal(list.dpSleepKoTails,false);});

test('Damage Switch restricts both counter endpoints to Pokemon SP',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.active.cards=[];p.bench[0].cards=[];p.bench[1].cards=[];dpPut(m,'pl2-103',p.active);dpPut(m,'pl2-76',p.bench[0]);dpPut(m,'dp1-76',p.bench[1]);p.bench[0].damage=20;M.apply(m,{type:'ability',player:p.id,name:'Damage Switch',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);assert.ok(prompt.options.blocked.some(t=>t.slot===R.SlotType.BENCH&&t.index===1));answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}]);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt.options.blocked.some(t=>t.slot===R.SlotType.BENCH&&t.index===0));answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);assert.equal(p.bench[0].damage,10);assert.equal(p.active.damage,10);});

test('Lucky Egg draws only after an attack knockout actually puts its Pokemon in discard',()=>{for(const lost of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];dpPut(m,'dp1-76',p.active);dpPut(m,'base1-98',p.active);dpPut(m,'base1-98',p.active);const defender=dpPut(m,'dp1-76',o.active);defender.hp=20;defender.weakness=[];dpPut(m,'dp1-76',o.bench[0]);const egg=dpPut(m,'pl4-88',o.active);o.active.tools.push(egg);o.hand.cards=[];if(lost)o.active.marker.addMarker('LOST_CITY_MARKER',defender);M.apply(m,{type:'attack',player:p.id,name:'Ember'});drain(m);assert.ok((lost?o.lostzone:o.discard).cards.includes(defender));assert.equal(o.hand.cards.length,lost?0:7);}});
test('Magical Return detaches a persistent Technical Machine while preserving its Pokemon',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.active.cards=[];dpPut(m,'pl2-110',p.active);const machine=dpPut(m,'pl2-95',p.active);M.apply(m,{type:'ability',player:p.id,name:'Magical Return',target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);assert.ok(p.hand.cards.includes(machine));assert.equal(p.active.getPokemonCard()._labId,'pl2-110');});

test('Flame Bluster requires two physical Fire Energy cards even when one attachment supplies four units',()=>{const m=setup('dppl',dpDeck);let [p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];dpPut(m,'dp2-123',p.active);const energy=dpPut(m,'base1-98',p.active);energy.provides=Array(4).fill(R.CardType.FIRE);const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];const journal=m.journal.length;assert.throws(()=>M.apply(m,{type:'attack',player:p.id,name:'Flame Bluster'}),e=>e.message==='NOT_ENOUGH_ENERGY');assert.equal(m.journal.length,journal);assert.equal(o.active.damage,0);[p,o]=m.store.state.players;dpPut(m,'base1-98',p.active);M.apply(m,{type:'attack',player:p.id,name:'Flame Bluster'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);assert.equal(prompt.options.min,2);answer(m,prompt,[0,1]);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.TOP_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);assert.equal(o.active.damage,100);});

test('Primal Shell blocks Items and Tools before either card leaves hand',()=>{for(const id of ['dp1-118','dp7-83']){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;o.active.cards=[];dpPut(m,'dp5-6',o.active);p.active.damage=20;p.hand.cards=[];dpPut(m,id,p.hand);const journal=m.journal.length;assert.throws(()=>M.apply(m,{type:'play',player:p.id,index:0,target}));assert.equal(m.journal.length,journal);assert.ok(m.store.state.players[0].hand.cards.some(card=>card._labId===id));assert.equal(m.store.state.players[0].active.damage,20);}});
test('DP Trainer searches include Items and Tools while excluding Supporters and Stadiums',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.active.cards=[];dpPut(m,'dp1-43',p.active);p.deck.cards=[];for(const id of ['dp1-118','dp7-83','pl4-90','pl1-111'])dpPut(m,id,p.deck);M.apply(m,{type:'attack',player:p.id,name:'Errand-Running'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);const index=id=>p.deck.cards.findIndex(card=>card._labId===id);assert.ok(!prompt.options.blocked.includes(index('dp1-118')));assert.ok(!prompt.options.blocked.includes(index('dp7-83')));assert.ok(prompt.options.blocked.includes(index('pl4-90')));assert.ok(prompt.options.blocked.includes(index('pl1-111')));answer(m,prompt,[index('dp7-83')]);assert.ok(p.hand.cards.some(card=>card._labId==='dp7-83'));});

test('Moon Skip adds its Prize only to the Defending Pokemon knockout caused by that attack',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];dpPut(m,'dp4-103',p.active);for(let i=0;i<3;i++)dpPut(m,'base1-101',p.active);const defender=dpPut(m,'dp1-76',o.active);defender.hp=10;defender.weakness=[];dpPut(m,'dp1-76',o.bench[0]);M.apply(m,{type:'attack',player:p.id,name:'Moon Skip'});drain(m);for(let i=0;i<10&&!M.pending(m).some(q=>q.type==='Choose prize');i++){const prompt=M.pending(m)[0];if(!prompt)break;if(prompt.type==='Choose pokemon')answer(m,prompt,[M.targets(m,prompt)[0].target]);else drain(m);}const prize=M.pending(m).find(q=>q.type==='Choose prize');assert.ok(prize);assert.equal(prize.options.count,2);});
