test('An Energy-unit discard can use one multi-unit card while a physical-card cost cannot',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];dpPut(m,'dp4-1',p.active);const energy=dpPut(m,'base1-98',p.active);energy.provides=Array(3).fill(R.CardType.FIRE);const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];M.apply(m,{type:'attack',player:p.id,name:'Flame Kick'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.TOP_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);assert.ok(p.discard.cards.includes(energy));assert.equal(o.active.damage,80);});

test('Doom Desire resolves at the opponent turn end and is removed when its target retreats',()=>{for(const retreat of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];const jirachi=dpPut(m,'dp6-31',p.active);jirachi.attacks.find(a=>a.name==='Doom Desire').cost=[];const energy=dpPut(m,'base1-98',p.active);const victim=dpPut(m,'dp1-76',o.active);victim.retreat=[];dpPut(m,'dp1-103',o.bench[0]);M.apply(m,{type:'attack',player:p.id,name:'Doom Desire'});drain(m);assert.ok(p.discard.cards.includes(energy));assert.ok(!o.discard.cards.includes(victim));if(retreat){M.apply(m,{type:'retreat',player:o.id,index:0});drain(m);}M.apply(m,{type:'pass',player:o.id});drain(m);assert.equal(o.discard.cards.includes(victim),!retreat);}});

test('A DP attack can discard Holons Castform from its real auxiliary Energy zone',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];dpPut(m,'dp1-76',p.active);const old=dpPut(m,'base1-98',p.active),holon=dpPut(m,'ex13-44',p.hand),defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];M.apply(m,M.handEnergyAction(p,p.hand.cards.indexOf(holon)));drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose pokemon');answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose energy');assert.ok(prompt);answer(m,prompt,[prompt.energy.findIndex(entry=>entry.card===old)]);drain(m);assert.ok(p.active.energies.cards.includes(holon));m.randomState=1;M.apply(m,{type:'attack',player:p.id,name:'Ember'});drain(m);prompt=M.pending(m).find(q=>q.type==='Choose cards'||q.type==='Choose energy');assert.ok(prompt);answer(m,prompt,[prompt.type==='Choose energy'?prompt.energy.findIndex(entry=>entry.card===holon):0]);drain(m);assert.ok(p.discard.cards.includes(holon));assert.ok(!p.active.energies.cards.includes(holon));assert.equal(o.active.damage,30);});

test('Rock Reaction distinguishes manual and Trainer attachments from attacks and Powers',()=>{for(const origin of ['manual','trainer','attack','power']){const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.bench[0].cards=[];dpPut(m,'dp5-89',p.bench[0]);const energy=dpPut(m,'base1-97',p.hand),evolution=new R.PokemonCard();Object.assign(evolution,{id:-992200,name:'Kabuto',fullName:'DP fossil evolution fixture',stage:R.Stage.STAGE_1,hp:80,evolvesFrom:'Dome Fossil',powers:[],attacks:[]});p.deck.cards=[evolution];const attach=new R.AttachEnergyEffect(p,energy,p.bench[0]);attach.origin=origin;m.store.reduceEffect(m.store.state,attach);assert.equal(M.pending(m).some(q=>q.type==='Choose cards'),['manual','trainer'].includes(origin));}});

test('Shoot Poison offers its Power after the real level-up card enters play',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.canEvolve=true;p.active.cards=[];const base=new R.PokemonCard();Object.assign(base,{id:-992210,name:'Gliscor',fullName:'DP previous Gliscor fixture',stage:R.Stage.STAGE_1,hp:100,evolvesFrom:'Gligar',powers:[],attacks:[]});p.active.cards=[base];p.active.pokemonPlayedTurn=3;const level=dpPut(m,'dp6-141',p.hand);M.apply(m,{type:'play',player:p.id,index:p.hand.cards.indexOf(level),target});drain(m);assert.equal(p.active.getPokemonCard(),level);const prompts=M.pending(m).filter(q=>q.type==='Select');assert.equal(prompts.length,1);answer(m,prompts[0],1);drain(m);assert.ok(o.active.specialConditions.includes(R.SpecialCondition.PARALYZED));assert.ok(o.active.specialConditions.includes(R.SpecialCondition.POISONED));});

