test('Dig Well privately selects top-three Water Energy and discards only the other top cards',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];dpPut(m,'pl1-2',p.active);p.deck.cards=[];const top=['dp1-76','dp1-103','tk-dp-m-12'].map(id=>dpPut(m,id,p.deck)),bottom=dpPut(m,'dp1-76',p.deck),attached=p.energyPlayedTurn;M.apply(m,{type:'ability',player:p.id,name:'Dig Well',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);assert.equal(prompt.playerId,p.id);assert.equal(prompt.options.max,1);answer(m,prompt,[2]);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[target]);drain(m);assert.ok(p.active.cards.includes(top[2]));assert.ok([top[0],top[1]].every(card=>p.discard.cards.includes(card)));assert.ok(p.deck.cards.includes(bottom));assert.equal(p.energyPlayedTurn,attached);});

test('Night Spin checks provided Energy units on the actual attacking Pokemon',()=>{for(const units of [2,3]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const dusknoir=dpPut(m,'dp7-1',p.active);dusknoir.attacks.find(a=>a.name==='Night Spin').cost=[];dusknoir.weakness=[];const attacker=dpPut(m,'dp1-76',o.active);attacker.hp=500;attacker.weakness=[];attacker.attacks[0].damage=30;const energy=dpPut(m,'base1-98',o.active);energy.provides=Array(units).fill(R.CardType.FIRE);M.apply(m,{type:'attack',player:p.id,name:'Night Spin'});drain(m);M.apply(m,{type:'attack',player:o.id,name:'Scratch'});drain(m);assert.equal(p.active.damage,units===2?0:30);}});

test('Conversion discards a basic Energy and expires after the current turn',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp4-6',p.active);p.hand.cards=[];const energy=dpPut(m,'tk-dp-m-12',p.hand);M.apply(m,{type:'ability',player:p.id,name:'Conversion',target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);let type=new R.CheckPokemonTypeEffect(p.active);m.store.reduceEffect(m.store.state,type);assert.deepEqual(Array.from(type.cardTypes),[R.CardType.WATER]);assert.ok(p.discard.cards.includes(energy));M.apply(m,{type:'pass',player:p.id});drain(m);type=new R.CheckPokemonTypeEffect(p.active);m.store.reduceEffect(m.store.state,type);assert.ok(!type.cardTypes.includes(R.CardType.WATER));});
test('Trash Burst counts discarded Energy cards rather than their provided units',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const rayquaza=dpPut(m,'pl3-8',p.active);rayquaza.attacks.find(a=>a.name==='Trash Burst').cost=[];const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];p.hand.cards=[];const energy=dpPut(m,'tk-dp-m-12',p.hand);energy.provides=Array(4).fill(R.CardType.WATER);M.apply(m,{type:'attack',player:p.id,name:'Trash Burst'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);assert.equal(o.active.damage,20);assert.ok(p.discard.cards.includes(energy));});

test('Scissor Blow applies self damage only when its damage actually knocks out the defender',()=>{for(const ko of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];const attacker=dpPut(m,'dp4-20',p.active);attacker.attacks.find(a=>a.name==='Scissor Blow').cost=[];attacker.weakness=[];const defender=dpPut(m,'dp1-76',o.active);defender.hp=ko?10:500;defender.weakness=[];dpPut(m,'dp1-76',o.bench[0]);M.apply(m,{type:'attack',player:p.id,name:'Scissor Blow'});drain(m);assert.equal(p.active.damage,ko?30:0);}});
test('Emperor Aura activates from a hand evolution and blocks the next turn hand attachment',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.canEvolve=true;p.active.cards=[];const lower=new R.PokemonCard();Object.assign(lower,{id:-992310,name:'Prinplup',fullName:'DP Emperor fixture',stage:R.Stage.STAGE_1,hp:80,evolvesFrom:'Piplup',powers:[],attacks:[]});p.active.cards=[lower];p.active.pokemonPlayedTurn=3;const empoleon=dpPut(m,'dp7-2',p.hand);M.apply(m,{type:'play',player:p.id,index:p.hand.cards.indexOf(empoleon),target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);assert.equal(o._dpNoHandAttach.turn,5);M.apply(m,{type:'pass',player:p.id});drain(m);const energy=dpPut(m,'tk-dp-m-12',o.hand);assert.throws(()=>m.store.reduceEffect(m.store.state,new R.AttachEnergyEffect(o,energy,o.active)));assert.ok(o.hand.cards.includes(energy));});

test('Iron Skull bypasses Resistance and defender Bodies during Rampardos attacks',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const attacker=dpPut(m,'pl1-13',p.active);attacker.tags.push(R.CardTag.POKEMON_SP);attacker.attacks.find(a=>a.name==='Mold Breaker').cost=[];const defender=dpPut(m,'pl4-28',o.active);defender.hp=500;defender.weakness=[];defender.resistance=[{type:R.CardType.FIGHTING,value:-20}];M.apply(m,{type:'attack',player:p.id,name:'Mold Breaker'});drain(m);assert.equal(o.active.damage,40);});
test('Unlucky Wind treats the opponents heads as tails during that opponents turn',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const attacker=dpPut(m,'tk-dp-m-5',p.active);attacker.attacks.find(a=>a.name==='Water Splash').cost=[];const defender=dpPut(m,'pl2-13',o.active);defender.hp=500;defender.weakness=[];m.randomState=7;M.apply(m,{type:'attack',player:p.id,name:'Water Splash'});drain(m);assert.equal(o.active.damage,20);});
test('Sunlight Veil adds twenty HP once to Eevee evolutions and excludes other Pokemon',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];p.bench[0].cards=[];p.bench[1].cards=[];const espeon=dpPut(m,'dp5-18',p.bench[0]);dpPut(m,'dp5-18',p.bench[1]);let hp=new R.CheckHpEffect(p,p.bench[0]);m.store.reduceEffect(m.store.state,hp);assert.equal(hp.hp,espeon.hp+20);hp=new R.CheckHpEffect(p,p.active);m.store.reduceEffect(m.store.state,hp);assert.equal(hp.hp,p.active.getPokemonCard().hp);});

test('Ferment Poison suppresses the actual Body and curing or replacing Poison releases it',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const shuckle=dpPut(m,'dp3-109',p.active);shuckle.attacks[0].cost=[];dpPut(m,'dp5-32',o.active);M.apply(m,{type:'attack',player:p.id,name:'Ferment Poison'});drain(m);let check=new R.CheckPokemonStatsEffect(o.active);m.store.reduceEffect(m.store.state,check);assert.ok(check.weakness.length);assert.ok(o.active.specialConditions.includes(R.SpecialCondition.POISONED));o.active.removeSpecialCondition(R.SpecialCondition.POISONED);check=new R.CheckPokemonStatsEffect(o.active);m.store.reduceEffect(m.store.state,check);assert.equal(check.weakness.length,0);o.active.addSpecialCondition(R.SpecialCondition.POISONED);check=new R.CheckPokemonStatsEffect(o.active);m.store.reduceEffect(m.store.state,check);assert.equal(check.weakness.length,0);});
test('Poison Sacs preserves Poison through level-up only while the opposing Body is present',()=>{for(const body of [false,true]){const {m,p,o,level}=dpLevelFixture();o.active.cards=[];dpPut(m,body?'dp2-36':'dp1-76',o.active);p.active.specialConditions=[R.SpecialCondition.POISONED];M.apply(m,{type:'play',player:p.id,index:p.hand.cards.indexOf(level),target});drain(m);assert.equal(p.active.specialConditions.includes(R.SpecialCondition.POISONED),body);}});

test('Outbreak Power allows distinct targets up to attached Energy units and applies Active Weakness once',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];const attacker=dpPut(m,'dp7-28',p.active);attacker.attacks.find(a=>a.name==='Outbreak Power').cost=[];const energy=dpPut(m,'base1-97',p.active);energy.provides=Array(3).fill(R.CardType.FIGHTING);const active=dpPut(m,'dp1-76',o.active),bench=dpPut(m,'dp1-76',o.bench[0]);active.hp=bench.hp=500;active.weakness=[{type:R.CardType.METAL,value:20}];bench.weakness=[{type:R.CardType.METAL,value:20}];M.apply(m,{type:'attack',player:p.id,name:'Outbreak Power'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);assert.equal(prompt.options.min,0);assert.ok(prompt.options.max>=2);answer(m,prompt,[{player:R.PlayerType.TOP_PLAYER,slot:R.SlotType.ACTIVE,index:0},{player:R.PlayerType.TOP_PLAYER,slot:R.SlotType.BENCH,index:0}]);drain(m);assert.equal(o.active.damage,40);assert.equal(o.bench[0].damage,20);});
test('Ancient Guidance places a real Trainer Fossil from the deck without treating it as hand entry',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];dpPut(m,'dp5-67',p.active);p.deck.cards=[];const fossil=dpPut(m,'dp5-91',p.deck);assert.equal(fossil.superType,R.SuperType.TRAINER);m.randomState=7;M.apply(m,{type:'ability',player:p.id,name:'Ancient Guidance',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[p.deck.cards.indexOf(fossil)]);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,0);drain(m);assert.equal(p.bench[0].getPokemonCard(),fossil);assert.ok(fossil._dpEntryId>0);assert.equal(p.bench[0].damage,0);});
test('Disrupting Spy privately reorders the opponents actual top four after hand placement',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.bench[0].cards=[];const chatot=dpPut(m,'pl3-54',p.hand),top=o.deck.cards.slice(0,4);M.apply(m,{type:'play',player:p.id,index:p.hand.cards.indexOf(chatot),target:{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Order cards');assert.ok(prompt);assert.equal(prompt.playerId,p.id);answer(m,prompt,[3,2,1,0]);drain(m);assert.deepEqual(o.deck.cards.slice(0,4),top.slice().reverse());});

test('Burst Ball pays Energy units across real own field zones and rejects an insufficient field',()=>{for(const enough of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];p.bench[0].cards=[];o.active.cards=[];const raichu=dpPut(m,'dp7-8',p.active);raichu.attacks.find(a=>a.name==='Burst Ball').cost=[];const first=dpPut(m,'base1-100',p.active);dpPut(m,'dp1-76',p.bench[0]);let second;if(enough){second=dpPut(m,'base1-100',p.bench[0]);second.provides=Array(2).fill(R.CardType.LIGHTNING);}const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];if(!enough){assert.throws(()=>M.apply(m,{type:'attack',player:p.id,name:'Burst Ball'}));continue;}M.apply(m,{type:'attack',player:p.id,name:'Burst Ball'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0,1]);drain(m);assert.ok(p.discard.cards.includes(first));assert.ok(p.discard.cards.includes(second));assert.equal(o.active.damage,100);}});
test('Toss and Turn remains usable while Asleep when inherited by Snorlax Level-Up',()=>{for(const level of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const snorlax=dpPut(m,'pl2-81',p.active);snorlax.attacks.find(a=>a.name==='Toss and Turn').cost=[];if(level)dpPut(m,'pl2-111',p.active);p.active.specialConditions=[R.SpecialCondition.ASLEEP];const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];M.apply(m,{type:'attack',player:p.id,name:'Toss and Turn'});drain(m);assert.equal(o.active.damage,50);}});

test('Fainting Spell queues the actual attacker with the original knockout before Prizes',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];p.bench[0].cards=[];o.bench[0].cards=[];const attacker=dpPut(m,'dp1-76',p.active);attacker.attacks[0].damage=100;const gengar=dpPut(m,'dp7-18',o.active);gengar.hp=10;gengar.weakness=[];dpPut(m,'dp1-76',p.bench[0]);dpPut(m,'dp1-76',o.bench[0]);m.randomState=7;M.apply(m,{type:'attack',player:p.id,name:'Scratch'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);assert.equal(prompt.playerId,o.id);answer(m,prompt,1);drain(m);assert.ok(p.discard.cards.includes(attacker));assert.ok(o.discard.cards.includes(gengar));const prizes=M.pending(m).filter(q=>q.type==='Choose prize');assert.ok(prizes.some(q=>q.playerId===p.id));const firstPrize=prizes.find(q=>q.playerId===p.id);answer(m,firstPrize,[p.prizes.findIndex(list=>list.cards.length)]);drain(m);assert.ok(M.pending(m).some(q=>q.type==='Choose prize'&&q.playerId===o.id));});
test('Airy Wall counts physical attachments and Mime Jr adds protection from attack effects',()=>{for(const baby of [false,true]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];const shuckle=dpPut(m,'dp3-109',p.active);shuckle.attacks[0].cost=[];const mime=dpPut(m,'dp2-30',o.active);mime.weakness=[];if(baby){const lower=new R.PokemonCard();Object.assign(lower,{id:-992910,name:'Mime Jr.',fullName:'DP Airy fixture',stage:R.Stage.BASIC,hp:40,powers:[],attacks:[]});o.active.cards.unshift(lower);}const energy=dpPut(m,'base1-100',p.active);energy.provides=Array(4).fill(R.CardType.GRASS);M.apply(m,{type:'attack',player:p.id,name:'Ferment Poison'});drain(m);assert.equal(o.active.damage,baby?0:10);assert.equal(o.active.specialConditions.includes(R.SpecialCondition.POISONED),!baby);}});

test('Phoenix Turn keeps Ho-Oh and its Energy while discarding Tools and awarding the knockout Prize',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];dpPut(m,'dp1-76',p.active).attacks[0].damage=100;const hooh=dpPut(m,'dp3-10',o.active);hooh.hp=10;hooh.weakness=[];const energy=dpPut(m,'tk-dp-m-12',o.active),tool=dpPut(m,'pl1-110',o.active);o.active.tools.push(tool);m.randomState=7;M.apply(m,{type:'attack',player:p.id,name:'Scratch'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);assert.equal(o.active.getPokemonCard(),hooh);assert.equal(o.active.damage,0);assert.ok(o.active.cards.includes(energy));assert.ok(o.discard.cards.includes(tool));assert.ok(!o.discard.cards.includes(hooh));const prize=M.pending(m).find(q=>q.type==='Choose prize');assert.ok(prize);assert.equal(prize.playerId,p.id);assert.equal(prize.options.count,1);});
test('Memory Out locks that attack on the attackers next turn and retreat clears its Pokemon marker',()=>{const m=setup('dppl',dpDeck);let [p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];o.active.cards=[];const attacker=dpPut(m,'dp1-76',p.active);attacker.retreat=[];dpPut(m,'dp1-76',p.bench[0]);const uxie=dpPut(m,'dp2-18',o.active);uxie.hp=500;uxie.weakness=[];M.apply(m,{type:'attack',player:p.id,name:'Scratch'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);M.apply(m,{type:'pass',player:o.id});drain(m);assert.throws(()=>M.apply(m,{type:'attack',player:p.id,name:'Scratch'}));[p,o]=m.store.state.players;M.apply(m,{type:'retreat',player:p.id,index:0});drain(m);M.apply(m,{type:'attack',player:p.id,name:'Scratch'});drain(m);assert.equal(o.active.damage,20);});

test('Unown GUARD becomes a Tool, blocks attack effects, and returns to a Pokemon in hand',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];o.active.cards=[];dpPut(m,'pl2-110',p.active);p.active.getPokemonCard().weakness=[];const guard=dpPut(m,'dp4-57',p.bench[0]),energy=dpPut(m,'tk-dp-m-12',p.bench[0]);const shuckle=dpPut(m,'dp3-109',o.active);shuckle.attacks[0].cost=[];M.apply(m,{type:'ability',player:p.id,name:'GUARD',target:{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[target]);drain(m);assert.equal(guard.superType,R.SuperType.TRAINER);assert.equal(guard.trainerType,R.TrainerType.TOOL);assert.ok(p.active.tools.includes(guard));assert.ok(p.discard.cards.includes(energy));assert.equal(p.bench[0].getPokemonCard(),undefined);M.apply(m,{type:'pass',player:p.id});drain(m);M.apply(m,{type:'attack',player:o.id,name:'Ferment Poison'});drain(m);assert.equal(p.active.damage,10);assert.ok(!p.active.specialConditions.includes(R.SpecialCondition.POISONED));M.apply(m,{type:'ability',player:p.id,name:'Magical Return',target});drain(m);prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);assert.ok(p.hand.cards.includes(guard));assert.equal(guard.superType,R.SuperType.POKEMON);assert.ok(!guard._dpPokemonToolRole);assert.ok(!p.active.tools.includes(guard));});

test('Decode keeps selected cards private and orders them above the shuffled remainder',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp5-100',p.active);M.apply(m,{type:'ability',player:p.id,name:'Decode',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);const chosen=p.deck.cards.slice(0,2);answer(m,prompt,[0,1]);drain(m);prompt=M.pending(m).find(q=>q.type==='Shuffle deck');assert.ok(prompt);answer(m,prompt,p.deck.cards.map((_,i)=>i));drain(m);prompt=M.pending(m).find(q=>q.type==='Order cards');assert.ok(prompt);assert.equal(prompt.playerId,p.id);answer(m,prompt,[1,0]);drain(m);assert.deepEqual(p.deck.cards.slice(0,2),chosen.reverse());});
test('Osmotic Pressure moves only the chosen counters from East Sea to West Sea',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];dpPut(m,'dp3-8',p.active);const west=new R.PokemonCard();Object.assign(west,{id:-993110,name:'Gastrodon West Sea',fullName:'DP West fixture',stage:R.Stage.STAGE_1,hp:100,powers:[],attacks:[]});p.bench[0].cards=[west];p.active.damage=40;M.apply(m,{type:'ability',player:p.id,name:'Osmotic Pressure',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}]);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,3);drain(m);assert.equal(p.active.damage,10);assert.equal(p.bench[0].damage,30);});

test('Fin Luster places the chosen Basic from the opponent hand then makes it Active',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp7-4',p.active);o.hand.cards=[];o.bench[0].cards=[];const chosen=dpPut(m,'dp1-76',o.hand),old=o.active.getPokemonCard();M.apply(m,{type:'ability',player:p.id,name:'Fin Luster',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Show cards');assert.ok(prompt);assert.equal(prompt.playerId,p.id);answer(m,prompt,true);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[o.hand.cards.indexOf(chosen)]);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,0);drain(m);assert.equal(o.active.getPokemonCard(),chosen);assert.ok(o.bench.some(list=>list.getPokemonCard()===old));assert.ok(!o.hand.cards.includes(chosen));});
test('Toxic Virus adds checkup poison counters without changing the stored poison strength',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.bench[0].cards=[];dpPut(m,'dp4-31',p.bench[0]);o.active.specialConditions=[R.SpecialCondition.POISONED];o.active.poisonDamage=20;const before=o.active.damage;M.apply(m,{type:'pass',player:p.id});drain(m);assert.equal(o.active.damage-before,30);assert.equal(o.active.poisonDamage,20);});

test('Energy Reaction responds to a real hand attachment once and uses the attached type',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp6-45',p.active);const energy=dpPut(m,'base1-99',p.hand);m.store.reduceEffect(m.store.state,new R.AttachEnergyEffect(p,energy,p.active));drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);assert.ok(o.active.specialConditions.includes(R.SpecialCondition.ASLEEP));assert.ok(!o.active.specialConditions.includes(R.SpecialCondition.POISONED));});

test('Dragon DNA borrows the real Basic attack and adds thirty damage before weakness',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;p.active.cards=[];o.active.cards=[];dpPut(m,'dp2-89',p.active);dpPut(m,'dp2-26',p.active);p.active.damage=20;const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];dpPut(m,'tk-dp-m-12',p.active);assert.ok(M.attacks(m,p).some(attack=>attack.name==='Flail'));M.apply(m,{type:'attack',player:p.id,name:'Flail'});drain(m);assert.equal(o.active.damage,50);});

test('Supreme Command removes hidden cards from hand and returns them after the opponents turn',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp1-120',p.active);const count=o.hand.cards.length;M.apply(m,{type:'ability',player:p.id,name:'Supreme Command',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);const card=o.hand.cards[0];answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,0);drain(m);assert.equal(o.hand.cards.length,count-1);assert.ok(!o.hand.cards.includes(card));M.apply(m,{type:'pass',player:p.id});drain(m);assert.ok(!o.hand.cards.includes(card));M.apply(m,{type:'pass',player:o.id});drain(m);assert.ok(o.hand.cards.includes(card));assert.equal(o._dpCommandEscrow.length,0);});
test('Energetic Impulse heads changes Lazy Blow base damage for this turn',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];const slaking=dpPut(m,'dp2-34',p.active);slaking.attacks[0].cost=[];const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];m.randomState=7;M.apply(m,{type:'ability',player:p.id,name:'Energetic Impulse',target});drain(m);M.apply(m,{type:'attack',player:p.id,name:'Lazy Blow'});drain(m);assert.equal(o.active.damage,130);});

test('Effect evolution clears conditions, keeps damage, and records the previous Pokemon once',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];const abra=dpPut(m,'dp2-69',p.active);abra.attacks.find(attack=>attack.name==='Ultra Evolution').cost=[];p.active.damage=10;p.active.specialConditions=[R.SpecialCondition.POISONED];p.deck.cards=[];const alakazam=new R.PokemonCard();Object.assign(alakazam,{id:-994110,name:'Alakazam',fullName:'DP effect evolution fixture',stage:R.Stage.STAGE_2,evolvesFrom:'Kadabra',hp:100,powers:[],attacks:[]});p.deck.cards=[alakazam];M.apply(m,{type:'attack',player:p.id,name:'Ultra Evolution'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);prompt=M.pending(m).find(q=>q.type==='Shuffle deck');if(prompt)answer(m,prompt,p.deck.cards.map((_,i)=>i));drain(m);assert.equal(p.active.getPokemonCard(),alakazam);assert.equal(p.active.damage,10);assert.equal(p.active.specialConditions.length,0);assert.equal(p.active._dpEvolutionHistory.from,'Abra');assert.ok(p.active._dpEvolutionHistory.conditions.includes(R.SpecialCondition.POISONED));});

test('Heat Wave recovers only basic Energy actually discarded by the active attackers attack',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];o.active.cards=[];dpPut(m,'dp1-76',p.active);dpPut(m,'dp7-97',p.bench[0]);const fire=dpPut(m,'base1-98',p.active);dpPut(m,'base1-98',p.active);const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];m.randomState=1;M.apply(m,{type:'attack',player:p.id,name:'Ember'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards'||q.type==='Choose energy');assert.ok(prompt);answer(m,prompt,[prompt.type==='Choose energy'?prompt.energy.findIndex(entry=>entry.card===fire):0]);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[p.discard.cards.indexOf(fire)]);drain(m);assert.ok(p.active.cards.includes(fire));assert.ok(!p.discard.cards.includes(fire));});

test('Ectoplasm replaces the knocked out Pokemon with a Stadium and restores it when discarded',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];dpPut(m,'dp1-76',p.active).attacks[0].damage=100;const dusknoir=dpPut(m,'dp7-96',o.active);dusknoir.hp=10;dusknoir.weakness=[];const energy=dpPut(m,'base1-98',o.active);dpPut(m,'dp1-76',o.bench[0]);M.apply(m,{type:'attack',player:p.id,name:'Scratch'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);assert.ok(o.stadium.cards.includes(dusknoir));assert.ok(o.discard.cards.includes(energy));assert.equal(dusknoir.superType,R.SuperType.TRAINER);assert.equal(dusknoir.trainerType,R.TrainerType.STADIUM);assert.ok(M.pending(m).some(q=>q.type==='Choose prize'&&q.playerId===p.id));const previous=R.CardList.wotcMovementContext;R.CardList.wotcMovementContext={state:m.store.state,actorId:p.id,kind:'attack'};try{o.stadium.moveCardsTo([dusknoir],o.discard);}finally{R.CardList.wotcMovementContext=previous;}assert.ok(o.hand.cards.includes(dusknoir));assert.ok(!o.discard.cards.includes(dusknoir));assert.equal(dusknoir.superType,R.SuperType.POKEMON);assert.ok(!dusknoir._dpPokemonStadiumRole);});

test('Energy Shift turns a self-knocked-out Electrode into one rainbow Energy and preserves the Prize',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];o.active.cards=[];const electrode=dpPut(m,'dp3-26',p.active);electrode.attacks[0].cost=[];dpPut(m,'dp1-76',p.bench[0]);const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];M.apply(m,{type:'attack',player:p.id,name:'Ion Blast'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}]);drain(m);assert.ok(p.bench[0].energies.cards.includes(electrode)||p.active.energies.cards.includes(electrode));assert.equal(electrode.superType,R.SuperType.ENERGY);assert.equal(electrode.energyType,R.EnergyType.SPECIAL);assert.equal(electrode.provides.length,1);assert.equal(electrode.provides[0],R.CardType.ANY);assert.ok(M.pending(m).some(q=>q.type==='Choose prize'&&q.playerId===o.id));});

function dpSprayBench(m,o){o.hand.cards=[];const spray=dpPut(m,'pl1-117',o.hand);for(let i=0;i<3;i++){o.bench[i].cards=[];dpPut(m,'pl1-47',o.bench[i]);}return spray;}
test('Power Spray cancels effects before a draw, consumes the card, retains use and triggers Primal Claw',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp2-6',p.active);const spray=dpSprayBench(m,o);o.bench[3].cards=[];dpPut(m,'dp5-15',o.bench[3]);const hand=p.hand.cards.slice(),deck=p.deck.cards.slice();M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);assert.equal(prompt.playerId,o.id);answer(m,prompt,1);drain(m);assert.deepEqual(p.hand.cards,hand);assert.deepEqual(p.deck.cards,deck);assert.ok(o.discard.cards.includes(spray));assert.equal(p.active.damage,20);assert.throws(()=>M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target}));});
test('Power Cancel pays its own two-card discard and stops the opponents Power',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.bench[0].cards=[];dpPut(m,'dp2-6',p.active);dpPut(m,'dp2-2',o.bench[0]);o.hand.cards=[];const cards=[dpPut(m,'base1-98',o.hand),dpPut(m,'base1-98',o.hand)];const hand=p.hand.cards.length;M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0,1]);drain(m);assert.equal(p.hand.cards.length,hand);assert.ok(cards.every(card=>o.discard.cards.includes(card)));});
test('A native hand-entry Set Up Power can be sprayed before drawing',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.hand.cards=[];p.bench[0].cards=[];const uxie=dpPut(m,'dp6-43',p.hand),spray=dpSprayBench(m,o),deck=p.deck.cards.slice();M.apply(m,{type:'play',player:p.id,index:0,target:{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}});drain(m);let prompt=M.pending(m).find(q=>q.type==='Confirm');assert.ok(prompt);answer(m,prompt,true);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);assert.equal(prompt.playerId,o.id);answer(m,prompt,1);drain(m);assert.equal(p.bench[0].getPokemonCard(),uxie);assert.equal(p.hand.cards.length,0);assert.deepEqual(p.deck.cards,deck);assert.ok(o.discard.cards.includes(spray));});

test('Cancelled Vacation still ends the turn without healing',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp6-79',p.active);p.active.damage=20;dpSprayBench(m,o);M.apply(m,{type:'ability',player:p.id,name:'VACATION',target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);assert.equal(prompt.playerId,o.id);answer(m,prompt,1);drain(m);assert.equal(p.active.damage,20);assert.equal(m.store.state.turn,5);assert.equal(m.store.state.players[m.store.state.activePlayer].id,o.id);});
test('Darkness Drive reacts to a cancelled opponent Power as a Body attachment',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];dpPut(m,'dp2-6',p.active);dpPut(m,'dp7-30',o.active);dpSprayBench(m,o);const dark=dpPut(m,'base1-98',o.discard);dark.provides=[R.CardType.DARK];M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);assert.equal(prompt.playerId,o.id);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[o.discard.cards.indexOf(dark)]);drain(m);assert.ok(o.active.cards.includes(dark));assert.equal(o.energyPlayedTurn,0);});

test('Link Lightning resolves Voltage Shoot then offers an affordable inherited second attack',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.canEvolve=true;p.active.cards=[];const lower=dpPut(m,'dp7-8',p.active);lower.attacks.find(attack=>attack.name==='Slice').cost=[];p.active.pokemonPlayedTurn=3;const level=dpPut(m,'dp7-99',p.hand);M.apply(m,{type:'play',player:p.id,index:p.hand.cards.indexOf(level),target});drain(m);level.attacks[0].cost=[];p.hand.cards=[];dpPut(m,'base1-100',p.hand);dpPut(m,'base1-100',p.hand);o.active.cards=[];const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];M.apply(m,{type:'attack',player:p.id,name:'Voltage Shoot'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0,1]);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.TOP_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose attack');assert.ok(prompt);const options=prompt.cards.flatMap(card=>card.attacks);const index=options.findIndex(attack=>attack.name==='Slice');assert.ok(index>=0);answer(m,prompt,{index:0,attack:'Slice'});drain(m);assert.equal(o.active.damage,110);assert.equal(m.store.state.turn,5);});

test('Empty Bench slots are never evolved targets',()=>{const m=setup('dppl',dpDeck);assert.equal(m.store.state.players[0].bench[4].isEvolved(),false);});
test('Unown QUICK and EQUIP become working Tools and restore Pokemon identity on discard',()=>{for(const [id,name] of [['dp5-49','QUICK'],['dp2-65','EQUIP']]){const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];const host=dpPut(m,'dp1-76',p.active),unown=dpPut(m,id,p.bench[0]);host.retreat=[R.CardType.COLORLESS];M.apply(m,{type:'ability',player:p.id,name,target:{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[target]);drain(m);assert.ok(p.active.tools.includes(unown));assert.equal(unown.superType,R.SuperType.TRAINER);if(name==='QUICK'){const check=new R.CheckRetreatCostEffect(p);m.store.reduceEffect(m.store.state,check);assert.equal(check.cost.length,0);}else{const check=new R.CheckHpEffect(p,p.active);m.store.reduceEffect(m.store.state,check);assert.equal(check.hp,host.hp+10);}p.active.moveCardTo(unown,p.discard);assert.equal(unown.superType,R.SuperType.POKEMON);assert.ok(!unown._dpPokemonToolRole);}});
test('Unown RETIRE discards itself and attachments, draws one and gives no Prize',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.bench[0].cards=[];const unown=dpPut(m,'dp6-77',p.bench[0]),energy=dpPut(m,'base1-101',p.bench[0]),hand=p.hand.cards.length,prizes=o.prizes.filter(x=>x.cards.length).length;M.apply(m,{type:'ability',player:p.id,name:'RETIRE',target:{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}});drain(m);assert.ok(p.discard.cards.includes(unown)&&p.discard.cards.includes(energy));assert.equal(p.hand.cards.length,hand+1);assert.equal(o.prizes.filter(x=>x.cards.length).length,prizes);assert.equal(M.pending(m).length,0);});
test('Invalid conditioned Power is rejected before offering Power Spray',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp2-6',p.active);p.active.specialConditions=[R.SpecialCondition.POISONED];const spray=dpSprayBench(m,o);assert.throws(()=>M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target}));assert.equal(M.pending(m).length,0);assert.ok(m.store.state.players[1].hand.cards.includes(spray));});
test('Phoenix Turn discards Expert Belt before awarding the single Knock Out Prize',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];const attacker=dpPut(m,'dp1-76',p.active);attacker.attacks[0].damage=100;const hooh=dpPut(m,'dp3-10',o.active);hooh.hp=10;hooh.weakness=[];const belt=dpPut(m,'pl4-87',o.active);o.active.tools.push(belt);m.randomState=7;M.apply(m,{type:'attack',player:p.id,name:'Scratch'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose prize');assert.ok(prompt);assert.equal(prompt.options.count,1);assert.ok(o.discard.cards.includes(belt));assert.equal(o.active.getPokemonCard(),hooh);assert.equal(o.active.damage,0);});


test('Darkness Grace excludes Lv.X cards and evolves only a matching field Pokemon',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];p.bench[0].cards=[];dpPut(m,'pl4-32',p.active);dpPut(m,'dp7-34',p.bench[0]);p.deck.cards=[];const level=dpPut(m,'dp6-144',p.deck),evolution=dpPut(m,'dp7-1',p.deck);M.apply(m,{type:'attack',player:p.id,name:'Darkness Grace'});drain(m);let prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);assert.ok(prompt.options.blocked.includes(p.deck.cards.indexOf(level)));answer(m,prompt,[p.deck.cards.indexOf(evolution)]);drain(m);prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.BOTTOM_PLAYER,slot:R.SlotType.BENCH,index:0}]);drain(m);prompt=M.pending(m).find(q=>q.type==='Shuffle deck');if(prompt)answer(m,prompt,p.deck.cards.map((_,i)=>i));drain(m);assert.equal(p.bench[0].getPokemonCard(),evolution);assert.equal(p.active.damage,10);assert.equal(m.store.state.turn,5);});


test('Telepass and Download copy the Supporter effect without consuming the normal Supporter allowance',()=>{for(const [id,power] of [['dp3-7','Telepass'],['dp4-49','Download']]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,id,p.active);p.hand.cards=[];o.discard.cards=[];const supporter=dpPut(m,'dp5-83',power==='Telepass'?o.discard:p.hand),before=p.hand.cards.length,used=p.supporterTurn=4;M.apply(m,{type:'ability',player:p.id,name:power,target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[(power==='Telepass'?o.discard:p.hand).cards.indexOf(supporter)]);drain(m);assert.equal(p.hand.cards.length,before+(power==='Download'?1:2));assert.equal(p.supporterTurn,used);assert.ok((power==='Telepass'?o.discard:p.discard).cards.includes(supporter));assert.equal(M.pending(m).length,0);}});
test('Detour copies the played Supporter without moving it or altering the allowance',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];const jirachi=dpPut(m,'pl2-7',p.active);jirachi.attacks[0].cost=[];p.hand.cards=[];p.supporter.cards=[];const supporter=dpPut(m,'dp5-83',p.supporter);p.supportersForDetour.cards=[supporter];p.supporterTurn=4;M.apply(m,{type:'attack',player:p.id,name:'Detour'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[0]);drain(m);assert.equal(p.hand.cards.length,2);assert.ok(p.discard.cards.includes(supporter));assert.equal(p.supporterTurn,0);assert.equal(m.store.state.turn,5);});


test('DP targeted attacks finish harmlessly when no Pokemon meets their printed target condition',()=>{for(const [id,name] of [['dp1-15','Frustration'],['dp2-46','Triple Pick'],['pl4-55','Bunny Hop'],['dp6-71','Core Flash']]){const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];const attacker=dpPut(m,id,p.active);attacker.attacks.find(a=>a.name===name).cost=[];const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;defender.weakness=[];o.active.damage=10;M.apply(m,{type:'attack',player:p.id,name});drain(m);assert.equal(o.active.damage,10);assert.equal(m.store.state.turn,5);assert.equal(M.pending(m).length,0);}});
test('Lovely Kiss moves the available counters once without Weakness damage or invalid state',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];const jynx=dpPut(m,'dp3-30',p.active);jynx.attacks[1].cost=[];p.active.damage=20;const defender=dpPut(m,'dp1-76',o.active);defender.hp=500;M.apply(m,{type:'attack',player:p.id,name:'Lovely Kiss'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Choose pokemon');assert.ok(prompt);answer(m,prompt,[{player:R.PlayerType.TOP_PLAYER,slot:R.SlotType.ACTIVE,index:0}]);drain(m);assert.equal(p.active.damage,0);assert.equal(o.active.damage,20);assert.equal(m.store.state.turn,5);});
test('Premier Ball recovers a selected Lv.X from either zone and cleans up the played Item',()=>{for(const from of ['deck','discard']){const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.hand.cards=[];p.deck.cards=[];p.discard.cards=[];const level=dpPut(m,'dp6-144',p[from]);if(from==='discard')dpPut(m,'base1-101',p.deck);const ball=dpPut(m,'dp4-101',p.hand);M.apply(m,{type:'play',player:p.id,index:0,target});drain(m);let prompt=M.pending(m).find(q=>q.type==='Select');if(prompt){answer(m,prompt,1);drain(m);}prompt=M.pending(m).find(q=>q.type==='Choose cards');assert.ok(prompt);answer(m,prompt,[p[from].cards.indexOf(level)]);drain(m);prompt=M.pending(m).find(q=>q.type==='Show cards');if(prompt){answer(m,prompt,true);drain(m);}prompt=M.pending(m).find(q=>q.type==='Shuffle deck');if(prompt){answer(m,prompt,p.deck.cards.map((_,i)=>i));drain(m);}assert.ok(p.hand.cards.includes(level));assert.ok(p.discard.cards.includes(ball));assert.equal(M.pending(m).length,0);}});


test('Call for Family resolves with a full Bench instead of rejecting the attack',()=>{const m=setup('dppl',dpDeck),p=m.store.state.players[0];m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp4-93',p.active);dpPut(m,'base1-99',p.active);for(const slot of p.bench){slot.cards=[];dpPut(m,'dp1-76',slot);}const count=p.deck.cards.length;M.apply(m,{type:'attack',player:p.id,name:'Call for Family'});drain(m);const prompt=M.pending(m).find(q=>q.type==='Shuffle deck');assert.ok(prompt);answer(m,prompt,p.deck.cards.map((_,i)=>i));drain(m);assert.equal(p.deck.cards.length,count);assert.equal(m.store.state.turn,5);});


test('Crystal Guardians Dark Eyes reacts cumulatively after a cancelled DP Power',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];dpPut(m,'dp2-6',p.active);dpSprayBench(m,o);for(const index of [3,4]){o.bench[index].cards=[];dpPut(m,'ex14-97',o.bench[index]);}const hand=p.hand.cards.length;M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target});drain(m);const prompt=M.pending(m).find(q=>q.type==='Select');assert.ok(prompt);answer(m,prompt,1);drain(m);assert.equal(p.hand.cards.length,hand);assert.equal(p.active.damage,40);});
test('Cessation Crystal blocks both DP Powers and Bodies only while its holder is Active',()=>{const m=setup('dppl',dpDeck),[p,o]=m.store.state.players;m.store.state.turn=4;p.active.cards=[];o.active.cards=[];o.bench[0].cards=[];const source=dpPut(m,'dp2-6',p.active);dpPut(m,'dp1-76',o.active);dpPut(m,'dp1-76',o.bench[0]);const crystal=dpPut(m,'ex14-74',o.active);o.active.tools.push(crystal);for(const powerType of [R.PowerType.POKEPOWER,R.PowerType.POKEBODY])assert.throws(()=>m.store.reduceEffect(m.store.state,new R.PowerEffect(p,{name:'test',text:'',powerType},source)));assert.throws(()=>M.apply(m,{type:'ability',player:p.id,name:'Miracle Oracle',target}));const [np,no]=m.store.state.players;[no.active,no.bench[0]]=[no.bench[0],no.active];assert.doesNotThrow(()=>m.store.reduceEffect(m.store.state,new R.PowerEffect(np,{name:'test',text:'',powerType:R.PowerType.POKEPOWER},np.active.getPokemonCard())));});

